33	/**
34	 * 限时紧急插播 API 端到端测试：主流程、失败回滚、幂等、授权失效回退与并发边界。
35	 * 运行环境为 H2（MODE=MySQL）内存库，唯一约束、行锁与事务提交顺序均由真实数据库验证。
36	 */
37	@SpringBootTest
38	@AutoConfigureMockMvc
39	@ActiveProfiles("test")
40	class EmergencyOverrideApiTest {
41	
42	    private static final String DAY = "2026-09-22";
43	    private static final String GRANT_FROM = "2026-09-22T00:00:00.000+08:00";
44	    private static final String GRANT_TO = "2026-09-23T00:00:00.000+08:00";
45	    private static final String T_10 = "2026-09-22T10:00:00.000+08:00";
46	    private static final String T_11 = "2026-09-22T11:00:00.000+08:00";
47	    private static final String T_1020 = "2026-09-22T10:20:00.000+08:00";
48	    private static final String T_1025 = "2026-09-22T10:25:00.000+08:00";
49	    private static final String T_1030 = "2026-09-22T10:30:00.000+08:00";
50	    private static final String T_1035 = "2026-09-22T10:35:00.000+08:00";
51	    private static final String T_1040 = "2026-09-22T10:40:00.000+08:00";
52	
53	    @Autowired
54	    private MockMvc mvc;
55	
56	    @Autowired
57	    private ObjectMapper objectMapper;
58	
59	    // ---------- 主流程：创建、命中、结束时刻、取消释放 ----------
60	
61	    @Test
62	    void createHitEndBoundaryCancelAndRelease() throws Exception {
63	        Ctx ctx = newContext();
64	        publishProgram(ctx, "ov-seg", T_10, T_11);
65	
66	        // 创建即 ACTIVE；区间 10:20-10:40
67	        createOverride(ctx, "req-create", "ov-1", ctx.newsAsset, ctx.newsGrant, 5, T_1020, T_1040)
68	                .andExpect(status().isOk())
69	                .andExpect(jsonPath("$.overrideKey").value(ctx.key("ov-1")))
70	                .andExpect(jsonPath("$.status").value("ACTIVE"))
71	                .andExpect(jsonPath("$.priority").value(5))
72	                .andExpect(jsonPath("$.grantId").value(ctx.newsGrant))
73	                .andExpect(jsonPath("$.cancelRequestId").isEmpty())
74	                .andExpect(jsonPath("$.cancelledAt").isEmpty());
75	
76	        // 区间外仍是原节目
77	        playout(ctx, "2026-09-22T10:10:00.000+08:00")
78	                .andExpect(jsonPath("$.source").value("PROGRAM"))
79	                .andExpect(jsonPath("$.assetId").value(ctx.movieAsset));
80	        // 区间内：EMERGENCY 优先于已发布节目，返回素材与 overrideKey
81	        playout(ctx, T_1020)
82	                .andExpect(jsonPath("$.source").value("EMERGENCY"))
83	                .andExpect(jsonPath("$.assetId").value(ctx.newsAsset))
84	                .andExpect(jsonPath("$.overrideKey").value(ctx.key("ov-1")))
85	                .andExpect(jsonPath("$.publicationId").isEmpty())
86	                .andExpect(jsonPath("$.reason").isEmpty());
87	        playout(ctx, T_1030)
88	                .andExpect(jsonPath("$.source").value("EMERGENCY"));
89	        // 结束时刻不再命中（左闭右开）
90	        playout(ctx, T_1040)
91	                .andExpect(jsonPath("$.source").value("PROGRAM"));
92	
93	        // 取消
94	        postJson("/api/emergency-overrides/" + ctx.key("ov-1") + "/cancel",
95	                        Map.of("requestId", "req-cancel"))
96	                .andExpect(status().isOk())
97	                .andExpect(jsonPath("$.status").value("CANCELLED"))
98	                .andExpect(jsonPath("$.cancelRequestId").value("req-cancel"))
99	                .andExpect(jsonPath("$.cancelledAt").isNotEmpty());
100	
101	        // 明细保留取消情况与原授权关联
102	        getOverride(ctx, "ov-1")
103	                .andExpect(status().isOk())
104	                .andExpect(jsonPath("$.status").value("CANCELLED"))
105	                .andExpect(jsonPath("$.grantId").value(ctx.newsGrant))
106	                .andExpect(jsonPath("$.cancelRequestId").value("req-cancel"));
107	
108	        // 取消后播出回到节目
109	        playout(ctx, T_1030)
110	                .andExpect(jsonPath("$.source").value("PROGRAM"))
111	                .andExpect(jsonPath("$.assetId").value(ctx.movieAsset));
112	
113	        // 取消提交后释放该冲突范围：同频道同优先级与已取消区间重叠可再创建
114	        createOverride(ctx, "req-create-2", "ov-2", ctx.newsAsset, ctx.newsGrant, 5,
115	                        "2026-09-22T10:25:00.000+08:00", "2026-09-22T10:35:00.000+08:00")
116	                .andExpect(status().isOk())
117	                .andExpect(jsonPath("$.status").value("ACTIVE"));
118	    }
119	
120	    // ---------- 区间规则：相邻合法、跨优先级允许重叠、时长与同日校验 ----------
121	
122	    @Test
123	    void adjacentSamePriorityAndDifferentPriorityOverlapAllowed() throws Exception {
124	        Ctx ctx = newContext();
125	
126	        // 同频道同优先级相邻区间合法
127	        createOverride(ctx, "r1", "a", ctx.newsAsset, ctx.newsGrant, 5, T_1020, T_1030)
128	                .andExpect(status().isOk());
129	        createOverride(ctx, "r2", "b", ctx.newsAsset, ctx.newsGrant, 5, T_1030, T_1040)
130	                .andExpect(status().isOk());
131	
132	        // 不同优先级允许重叠
133	        createOverride(ctx, "r3", "c", ctx.alertAsset, ctx.alertGrant, 3, T_1020, T_1040)
134	                .andExpect(status().isOk());
135	
136	        // 时长恰为 30 分钟：合法
137	        createOverride(ctx, "r4", "d", ctx.newsAsset, ctx.newsGrant, 2,
138	                        "2026-09-22T14:00:00.000+08:00", "2026-09-22T14:30:00.000+08:00")
139	                .andExpect(status().isOk());
140	    }
141	
142	    @Test
143	    void invalidIntervalsReturnBadRequest() throws Exception {
144	        Ctx ctx = newContext();
145	
146	        // 400：结束不大于开始
147	        createOverride(ctx, "bad-1", "k1", ctx.newsAsset, ctx.newsGrant, 5, T_1030, T_1020)
148	                .andExpect(status().isBadRequest());
149	        // 400：时长超过 30 分钟（30 分 1 秒）
150	        createOverride(ctx, "bad-2", "k2", ctx.newsAsset, ctx.newsGrant, 5,
151	                        "2026-09-22T14:00:00.000+08:00", "2026-09-22T14:30:00.001+08:00")
152	                .andExpect(status().isBadRequest());
153	        // 400：跨业务日
154	        createOverride(ctx, "bad-3", "k3", ctx.newsAsset, ctx.newsGrant, 5,
155	                        "2026-09-22T23:50:00.000+08:00", "2026-09-23T00:10:00.000+08:00")
156	                .andExpect(status().isBadRequest());
157	        // 400：优先级越界（Bean Validation）
158	        mvc.perform(post("/api/emergency-overrides").contentType(MediaType.APPLICATION_JSON)
159	                        .content(objectMapper.writeValueAsString(overrideBody(
160	                                "bad-4", ctx.key("k4"), ctx.channel, ctx.newsAsset,
161	                                ctx.newsGrant, 10, T_1020, T_1030))))
162	                .andExpect(status().isBadRequest());
163	        // 400：缺少 requestId
164	        mvc.perform(post("/api/emergency-overrides").contentType(MediaType.APPLICATION_JSON)
165	                        .content(objectMapper.writeValueAsString(overrideBody(
166	                                null, ctx.key("k5"), ctx.channel, ctx.newsAsset,
167	                                ctx.newsGrant, 5, T_1020, T_1030))))
168	                .andExpect(status().isBadRequest());
169	
170	        // 失败回滚：非法参数不产生插播记录
171	        getOverride(ctx, "k2").andExpect(status().isNotFound());
172	    }
173	
174	    // ---------- 404 / 409 / 422 分支 ----------
175	
176	    @Test
177	    void notFoundConflictAndUnprocessableBranches() throws Exception {
178	        Ctx ctx = newContext();
179	
180	        // 404：频道/素材/授权/明细不存在
181	        createOverride(ctx, "nf-1", "nf1", ctx.newsAsset, ctx.newsGrant, 5, T_1020, T_1030)
182	                .andExpect(status().isOk());
183	        mvc.perform(post("/api/emergency-overrides").contentType(MediaType.APPLICATION_JSON)
184	                        .content(objectMapper.writeValueAsString(overrideBody(
185	                                "nf-2", ctx.key("nf2"), ctx.prefix + "ghost", ctx.newsAsset,
186	                                ctx.newsGrant, 5, T_1020, T_1030))))
187	                .andExpect(status().isNotFound());
188	        mvc.perform(post("/api/emergency-overrides").contentType(MediaType.APPLICATION_JSON)
189	                        .content(objectMapper.writeValueAsString(overrideBody(
190	                                "nf-3", ctx.key("nf3"), ctx.channel, ctx.prefix + "ghost",
191	                                ctx.newsGrant, 5, T_1020, T_1030))))
192	                .andExpect(status().isNotFound());
193	        createOverrideRaw("nf-4", ctx.key("nf4"), ctx.channel, ctx.newsAsset, 999999, 5,
194	                        T_1020, T_1030)
195	                .andExpect(status().isNotFound());
196	        getOverrideRaw(ctx.prefix + "ghost").andExpect(status().isNotFound());
197	        postJson("/api/emergency-overrides/" + ctx.prefix + "ghost/cancel",
198	                        Map.of("requestId", "nf-5"))
199	                .andExpect(status().isNotFound());
200	
201	        // 422：授权不属于该频道
202	        Ctx other = newContext();
203	        createOverrideRaw("nm-1", ctx.key("nm1"), ctx.channel, ctx.newsAsset,
204	                        other.newsGrant, 5, T_1020, T_1030)
205	                .andExpect(status().isUnprocessableEntity())
206	                .andExpect(jsonPath("$.error").value("GRANT_NOT_MATCHED"));
207	        // 422：授权素材不匹配（movie 的授权用于 news 素材）
208	        createOverrideRaw("nm-2", ctx.key("nm2"), ctx.channel, ctx.newsAsset,
209	                        ctx.movieGrant, 5, T_1020, T_1030)
210	                .andExpect(status().isUnprocessableEntity())
211	                .andExpect(jsonPath("$.error").value("GRANT_NOT_MATCHED"));
212	
213	        // 422：授权未完整覆盖区间（授权 10:00-10:20，插播 10:10-10:30）
214	        long shortGrant = createGrant(ctx.channel, ctx.newsAsset,
215	                "2026-09-22T10:00:00.000+08:00", "2026-09-22T10:20:00.000+08:00");
216	        createOverrideRaw("nc-1", ctx.key("nc1"), ctx.channel, ctx.newsAsset,
217	                        shortGrant, 5, "2026-09-22T10:10:00.000+08:00", T_1030)
218	                .andExpect(status().isUnprocessableEntity())
219	                .andExpect(jsonPath("$.error").value("GRANT_NOT_COVERING"));
220	
221	        // 422：保底素材不能用于插播（授权校验前即拒绝）
222	        createOverrideRaw("fb-1", ctx.key("fb1"), ctx.channel, ctx.fallbackAsset,
223	                        ctx.newsGrant, 5, T_1020, T_1030)
224	                .andExpect(status().isUnprocessableEntity())
225	                .andExpect(jsonPath("$.error").value("FALLBACK_ASSET_NOT_GRANTABLE"));
226	
227	        // 422：指定授权已撤销（撤销先提交）
228	        long revokedGrant = createGrant(ctx.channel, ctx.alertAsset, GRANT_FROM, GRANT_TO);
229	        postJson("/api/grants/" + revokedGrant + "/revoke", Map.of("requestId", "rv-g"))
230	                .andExpect(status().isOk());
231	        createOverrideRaw("rv-1", ctx.key("rv1"), ctx.channel, ctx.alertAsset,
232	                        revokedGrant, 5, T_1020, T_1030)
233	                .andExpect(status().isUnprocessableEntity())
234	                .andExpect(jsonPath("$.error").value("GRANT_INVALID"));
235	
236	        // 409：同频道同优先级 ACTIVE 区间重叠（端点相接之外的部分重叠）
237	        createOverrideRaw("ov-2", ctx.key("ov-2"), ctx.channel, ctx.alertAsset,
238	                        ctx.alertGrant, 5, T_1025, T_1035)
239	                .andExpect(status().isConflict())
240	                .andExpect(jsonPath("$.error").value("OVERRIDE_INTERVAL_CONFLICT"));
241	        // 与另一条不同优先级的区间重叠不受影响（已在上面验证 3 级可重叠；这里重叠已有 5 级 nf1）
242	        createOverrideRaw("ov-3", ctx.key("ov-3"), ctx.channel, ctx.alertAsset,
243	                        ctx.alertGrant, 9, T_1025, T_1035)
244	                .andExpect(status().isOk());
245	
246	        // 409：重复 overrideKey
247	        createOverrideRaw("dup-1", ctx.key("nf1"), ctx.channel, ctx.newsAsset,
248	                        ctx.newsGrant, 5, "2026-09-22T15:00:00.000+08:00",
249	                        "2026-09-22T15:10:00.000+08:00")
250	                .andExpect(status().isConflict())
251	                .andExpect(jsonPath("$.error").value("DUPLICATE_OVERRIDE_KEY"));
252	
253	        // 409：取消 ACTIVE 后再次取消
254	        postJson("/api/emergency-overrides/" + ctx.key("nf1") + "/cancel",
255	                        Map.of("requestId", "cancel-nf1"))
256	                .andExpect(status().isOk());
257	        postJson("/api/emergency-overrides/" + ctx.key("nf1") + "/cancel",
258	                        Map.of("requestId", "cancel-nf1-again"))
259	                .andExpect(status().isConflict())
260	                .andExpect(jsonPath("$.error").value("OVERRIDE_NOT_ACTIVE"));
261	    }
262	
263	    // ---------- 幂等 ----------
264	
