545	    private long createGrant(String channel, String asset, String from, String to) throws Exception {
546	        MvcResult result = postJson("/api/grants", Map.of(
547	                        "channelId", channel, "assetId", asset,
548	                        "validFrom", from, "validTo", to))
549	                .andExpect(status().isOk())
550	                .andReturn();
551	        return readJson(result).get("id").asLong();
552	    }
553	
554	    private ResultActions createOverride(Ctx ctx, String requestId, String shortKey, String assetId,
555	                                         long grantId, int priority, String start, String end)
556	            throws Exception {
557	        return createOverrideRaw(requestId, ctx.key(shortKey), ctx.channel, assetId,
558	                grantId, priority, start, end);
559	    }
560	
561	    private ResultActions createOverrideRaw(String requestId, String overrideKey, String channelId,
562	                                            String assetId, long grantId, int priority,
563	                                            String start, String end) throws Exception {
564	        return postJson("/api/emergency-overrides",
565	                overrideBody(requestId, overrideKey, channelId, assetId, grantId, priority, start, end));
566	    }
567	
568	    private static Map<String, Object> overrideBody(String requestId, String overrideKey,
569	                                                    String channelId, String assetId, long grantId,
570	                                                    int priority, String start, String end) {
571	        Map<String, Object> body = new LinkedHashMap<>();
572	        body.put("requestId", requestId);
573	        body.put("overrideKey", overrideKey);
574	        body.put("channelId", channelId);
575	        body.put("assetId", assetId);
576	        body.put("grantId", grantId);
577	        body.put("priority", priority);
578	        body.put("start", start);
579	        body.put("end", end);
580	        return body;
581	    }
582	
583	    private ResultActions playout(Ctx ctx, String at) throws Exception {
584	        return mvc.perform(get("/api/channels/" + ctx.channel + "/playout").param("at", at));
585	    }
586	
587	    private ResultActions getOverride(Ctx ctx, String shortKey) throws Exception {
588	        return getOverrideRaw(ctx.key(shortKey));
589	    }
590	
591	    private ResultActions getOverrideRaw(String overrideKey) throws Exception {
592	        return mvc.perform(get("/api/emergency-overrides/" + overrideKey));
593	    }
594	
595	    private ResultActions postJson(String url, Object body) throws Exception {
596	        return mvc.perform(post(url).contentType(MediaType.APPLICATION_JSON)
597	                .content(objectMapper.writeValueAsString(body)));
598	    }
599	
600	    private JsonNode readJson(MvcResult result) throws Exception {
601	        return objectMapper.readTree(result.getResponse().getContentAsString());
602	    }
603	
604	    private interface ThrowingSupplier {
605	        Integer get(int index) throws Exception;
606	    }
607	
608	    private List<Integer> runConcurrently(int threads, ThrowingSupplier action) throws Exception {
609	        ExecutorService pool = Executors.newFixedThreadPool(threads);
610	        CountDownLatch ready = new CountDownLatch(threads);
611	        CountDownLatch start = new CountDownLatch(1);
612	        List<Future<Integer>> futures = new ArrayList<>();
613	        for (int i = 0; i < threads; i++) {
614	            final int index = i;
615	            futures.add(pool.submit(() -> {
616	                ready.countDown();
617	                start.await(5, TimeUnit.SECONDS);
618	                return action.get(index);
619	            }));
620	        }
621	        ready.await(5, TimeUnit.SECONDS);
622	        start.countDown();
623	        List<Integer> results = new ArrayList<>();
624	        for (Future<Integer> future : futures) {
625	            results.add(future.get(30, TimeUnit.SECONDS));
626	        }
627	        pool.shutdownNow();
628	        return results;
629	    }
630	}
