    @Test
    void invalidIntervalsReturnBadRequest() throws Exception {
        Ctx ctx = newContext();

        // 400：结束不大于开始
        createOverride(ctx, "bad-1", "k1", ctx.newsAsset, ctx.newsGrant, T_1030, T_1020)
